window.AAQ_ASSIGN = {"unit": 4, "title": "Diseases, Disorders, Treatments and Therapies", "aims": [{"aim": "A", "title": "Examine biological molecules and pathways and their effect on the body"}, {"aim": "B", "title": "Understand the effects of physiological diseases and disorders, and associated treatments"}, {"aim": "C", "title": "Examine the development of innovative and future types of treatment for physiological diseases and disorders"}], "criteria": [{"code": "A.P1", "aims": "A", "grade": "P", "n": 1, "text": "Explain the roles of proteins, nucleic acids and lipids in maintaining physiological health."}, {"code": "A.M1", "aims": "A", "grade": "M", "n": 1, "text": "Discuss how disruption to biological molecules and processes can lead to one physiological disease or disorder."}, {"code": "A.D1", "aims": "A", "grade": "D", "n": 1, "text": "Evaluate the impact of one physiological disease or disorder on the person affected"}, {"code": "B.P2", "aims": "B", "grade": "P", "n": 2, "text": "Describe the effects of physiological diseases and disorders"}, {"code": "B.P3", "aims": "B", "grade": "P", "n": 3, "text": "Describe the treatments of physiological diseases and disorders."}, {"code": "B.M2", "aims": "B", "grade": "M", "n": 2, "text": "Discuss the effects on the individual of physiological diseases and disorders, and their treatments."}, {"code": "B.D2", "aims": "B", "grade": "D", "n": 2, "text": "Evaluate the effects of treatments of physiological diseases and disorders."}, {"code": "C.P4", "aims": "C", "grade": "P", "n": 4, "text": "Describe the development and testing of a drug or medicine that has been synthesised for a specific purpose."}, {"code": "C.M3", "aims": "C", "grade": "M", "n": 3, "text": "Discuss the problems that may arise during development and testing of drugs, medicines, and treatments."}, {"code": "C.D3", "aims": "C", "grade": "D", "n": 3, "text": "Evaluate the ethical, legal and moral issues of drug/medicine development, testing and treatments for a physiological disease or disorder."}], "guidance": [{"aims": "A", "paras": ["For distinction standard, students will draw on accurately referenced secondary source material to explain the relevance and/or significance of the normal and disrupted state of biological molecules for the physiological disease or disorder they have chosen. The impact of the disruption on the person suffering from the disease or disorder will be evaluated, with a conclusion given and justified. For merit standard, students will give a detailed explanation of how the disruption of biological molecules is involved in a physiological disease or disorder. This will include how the disruption causes the disease or disorder and how the disorder causes disruption to molecules and metabolism (where this is known). Students will need to give clear details of the changes to the structure of molecules and their implications. For pass standard, students will give examples to explain the roles of proteins, nucleic acids and lipids in terms of their structure and functions in maintaining normal body functions. The explanations must relate to the importance of these biological molecules in maintaining physiological health."]}, {"aims": "B", "paras": ["For distinction standard, students will give examples to help them evaluate the treatment of at least two different types of physiological diseases or disorders. Students should explore how the treatments ease the symptoms and how they address the underlying cause/s of the condition. They should also explore the side effects which may accompany these treatments, how these impact the person suffering from the disease or disorder and how these side effects might be mitigated. For merit standard, students will discuss the effects of at least two physiological diseases or disorder. This will include the development of the disease/disorder and how it affects the individual. It will also include the physiological basis of treatments, and the positive and negative effects they have. For pass standard, students will give clear descriptions of the effects and treatments of two physiological diseases and disorders on the individual. Students will include details of the treatments in terms of how they reduce symptoms as well as treating the underlying cause of these diseases and disorders."]}, {"aims": "C", "paras": ["For distinction standard, students will evaluate the ethical, moral, and legal issues relating to drug/medicine development and testing and the treatment/s used for one physiological disease or disorder. An understanding of the differences between ethics and morals will be demonstrated, and the dilemmas scientists and medical professionals face will be considered in relation to these treatments. For merit standard, students will discuss the difficulties that could be encountered during the development and testing of a drug, medicine of treatment for a specific physiological disease or disorder. The development and use of innovative treatments will be included, as will the importance of ethical and moral issues encountered when developing new drugs. For pass standard, students will describe the development and testing regime for a synthetic drug or medicine which is used for a named disorder or disease. Students must give an objective account of the stages of drug and medicine testing. They will need to include information on the requirements for drugs and medicines to be rigorously tested prior to being approved for use. Students must use technical language and demonstrate breadth of coverage of the unit."]}]};
